import FacebookIcon from "@mui/icons-material/Facebook";
import EmailIcon from "@mui/icons-material/Email";
import InstagramIcon from "@mui/icons-material/Instagram";
import PhoneIphoneIcon from "@mui/icons-material/PhoneIphone";
import "./Footer.css";

const Footer = () => {
  return (
    <footer className="footer">
      <div className="footer-container">
        {/* Brand */}
        <div className="footer-section">
          <img
            src="/logo.png" /* <-- Replace with your actual logo path */
            alt="Olio Ruocco Logo"
            className="footer-logo-img"
          />{" "}
          <p className="footer-text">
            Olio extravergine di oliva di qualità artigianale, coltivato con
            passione e tradizione.
          </p>
        </div>

        {/* Navigation */}
        <div className="footer-section">
          <h3 className="footer-title">Navigazione</h3>
          <ul className="footer-links">
            <li>
              <a href="/prodotti">Prodotti</a>
            </li>
            <li>
              <a href="/chi-siamo">Chi siamo</a>
            </li>
            <li>
              <a href="/blog">Blog</a>
            </li>
            <li>
              <a href="/contatti">Contatti</a>
            </li>
          </ul>
        </div>

        {/* Contact + Social */}
        <div className="footer-section">
          <h3 className="footer-title">Contatti</h3>
          <ul className="footer-contacts">
            <li>
              <PhoneIphoneIcon /> +39 333 1234567
            </li>
            <li>
              <EmailIcon /> info@olioruocco.it
            </li>
          </ul>
          <div className="footer-socials">
            <a href="https://facebook.com" aria-label="Facebook">
              <FacebookIcon />
            </a>
            <a href="https://instagram.com" aria-label="Instagram">
              <InstagramIcon />
            </a>
          </div>
        </div>
      </div>

      {/* Bottom bar */}
      <div className="footer-bottom">
        © {new Date().getFullYear()} Olio Ruocco. Tutti i diritti riservati.
      </div>
    </footer>
  );
};

export default Footer;
